function createAlcoholBurnerApparatus({
  parent,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  bodyRadius = 0.26,
  bodyHeight = 0.42,
  wickHeight = 0.18,
  materials = {},
  appearance = burnerFlame(),
  name = 'alcohol-burner',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  applyTransform(group, position, rotation);
  addToParent(parent, group);

  const glassMaterial = cloneMaterial(materials.glass, createDefaultGlassMaterial());
  const metalMaterial = cloneMaterial(
    materials.metal,
    new THREE.MeshStandardMaterial({ color: 0x7f8b95, roughness: 0.34, metalness: 0.62 })
  );

  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(bodyRadius * 0.9, bodyRadius, bodyHeight, 24),
    cloneMaterial(materials.body, glassMaterial)
  );
  body.position.y = bodyHeight * 0.5;
  group.add(body);

  const cap = new THREE.Mesh(
    new THREE.CylinderGeometry(bodyRadius * 0.34, bodyRadius * 0.4, 0.08, 20),
    metalMaterial
  );
  cap.position.y = bodyHeight + 0.04;
  group.add(cap);

  const wick = new THREE.Mesh(
    new THREE.CylinderGeometry(bodyRadius * 0.09, bodyRadius * 0.09, wickHeight, 16),
    cloneMaterial(materials.wick, new THREE.MeshStandardMaterial({ color: 0xdccfb4, roughness: 0.86 }))
  );
  wick.position.y = bodyHeight + wickHeight * 0.5 + 0.06;
  group.add(wick);

  const apparatus = composeApparatus({
    kind: 'alcohol-burner',
    family: 'heat-source',
    group,
    meshes: { body, cap, wick },
    anchors: {
      labelAnchor: makeAnchor(group, 0, bodyHeight + wickHeight + 0.48, 0, `${name}:labelAnchor`),
      gripAnchor: makeAnchor(group, 0, bodyHeight * 0.52, 0, `${name}:gripAnchor`),
      interactionZone: makeAnchor(group, 0, bodyHeight + wickHeight + 0.02, 0, `${name}:interactionZone`),
      heatZone: makeAnchor(group, 0, bodyHeight + wickHeight + 0.02, 0, `${name}:heatZone`),
      ignitionTip: makeAnchor(group, 0, bodyHeight + wickHeight + 0.08, 0, `${name}:ignitionTip`),
      flameOrigin: makeAnchor(group, 0, bodyHeight + wickHeight + 0.08, 0, `${name}:flameOrigin`),
    },
    constraints: {
      heatClearance: 0.16,
      effectBounds: {
        min: new THREE.Vector3(-bodyRadius, 0, -bodyRadius),
        max: new THREE.Vector3(bodyRadius, bodyHeight + wickHeight + 0.42, bodyRadius),
      },
    },
    meta: { appearance: appearance.name },
  });

  const { labelPlane } = attachFixedPlaneLabel({
    group,
    labelAnchor: apparatus.anchors.labelAnchor,
    planeGeometry: new THREE.PlaneGeometry(1.0, 0.38),
    role: 'floating-badge',
  });

  apparatus.controllers = {
    setEffectIntensity(value) {
      apparatus.state = apparatus.state || {};
      apparatus.state.effectIntensity = clamp(value, 0, 1);
    },
  };
  attachLabelController(apparatus, labelPlane, { defaultAccent: '#ff9b32' });
  apparatus.validators = [];
  return apparatus;
}

function createSolidReagentJarApparatus({
  parent,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  radius = 0.22,
  height = 0.7,
  neckRadius = 0.12,
  neckHeight = 0.12,
  wallThickness = 0.04,
  fillRatio = 0.72,
  pourPose = {},
  materials = {},
  appearance = yellowPrecipitate(),
  name = 'solid-reagent-jar',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  applyTransform(group, position, rotation);
  addToParent(parent, group);

  const glassMaterial = cloneMaterial(materials.glass, createDefaultGlassMaterial());
  const solidMaterial = cloneMaterial(
    materials.solid,
    appearance.createSurfaceMaterial({
      opacity: 0.94,
      roughness: 0.74,
      metalness: 0,
    })
  );
  const lidMaterial = cloneMaterial(
    materials.lid,
    new THREE.MeshStandardMaterial({ color: 0xeff4f8, roughness: 0.42, metalness: 0.08 })
  );

  const innerRadius = Math.max(radius - wallThickness, radius * 0.78);
  const bodyHeight = Math.max(height - neckHeight, height * 0.76);
  const innerHeight = Math.max(bodyHeight - wallThickness * 1.3, bodyHeight * 0.82);
  const baseY = wallThickness;
  const safeFillHeight = innerHeight * 0.92;
  const solidSurfaceY = baseY + safeFillHeight * clamp(fillRatio, 0, 1);

  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(radius * 0.9, radius, bodyHeight, 28),
    glassMaterial
  );
  body.position.y = bodyHeight * 0.5;
  body.castShadow = true;
  body.receiveShadow = true;
  group.add(body);

  const shoulder = new THREE.Mesh(
    new THREE.CylinderGeometry(neckRadius * 1.16, radius * 0.9, neckHeight * 0.78, 24),
    cloneMaterial(materials.shoulder, glassMaterial)
  );
  shoulder.position.y = bodyHeight + neckHeight * 0.18;
  shoulder.castShadow = true;
  group.add(shoulder);

  const neck = new THREE.Mesh(
    new THREE.CylinderGeometry(neckRadius, neckRadius * 1.06, neckHeight, 20),
    cloneMaterial(materials.neck, glassMaterial)
  );
  neck.position.y = bodyHeight + neckHeight * 0.5;
  neck.castShadow = true;
  group.add(neck);

  const bottom = new THREE.Mesh(
    new THREE.CylinderGeometry(innerRadius * 0.96, innerRadius * 0.98, wallThickness, 24),
    cloneMaterial(materials.base, glassMaterial)
  );
  bottom.position.y = wallThickness * 0.5;
  bottom.receiveShadow = true;
  group.add(bottom);

  const lid = new THREE.Mesh(
    new THREE.CylinderGeometry(neckRadius * 1.18, neckRadius * 1.24, 0.09, 20),
    lidMaterial
  );
  lid.position.y = bodyHeight + neckHeight + 0.045;
  lid.castShadow = true;
  group.add(lid);

  const solid = new THREE.Mesh(
    new THREE.CylinderGeometry(innerRadius * 0.96, innerRadius * 0.99, safeFillHeight, 20),
    solidMaterial
  );
  group.add(solid);

  const solidSurface = new THREE.Mesh(
    new THREE.CircleGeometry(innerRadius * 0.98, 20),
    cloneMaterial(materials.surface, appearance.createSurfaceMaterial({ opacity: 0.96, roughness: 0.78 }))
  );
  solidSurface.rotation.x = -Math.PI / 2;
  group.add(solidSurface);

  const granules = new THREE.Points(
    new THREE.BufferGeometry(),
    cloneMaterial(materials.granules, appearance.createPointsMaterial({ size: 0.032, opacity: 0.18 }))
  );
  const granulePositions = [];
  for (let i = 0; i < 44; i += 1) {
    const angle = (i / 44) * Math.PI * 2;
    const radiusScale = 0.2 + (i % 6) * 0.11;
    granulePositions.push(
      Math.cos(angle) * innerRadius * radiusScale,
      baseY + 0.04 + (i % 5) * 0.022,
      Math.sin(angle) * innerRadius * radiusScale
    );
  }
  granules.geometry.setAttribute('position', new THREE.Float32BufferAttribute(granulePositions, 3));
  group.add(granules);

  const mouthY = bodyHeight + neckHeight;
  const anchors = attachCommonContainerAnchors({
    group,
    name,
    labelY: mouthY + 0.32,
    labelPosition: [0, bodyHeight * 0.54, radius + 0.055],
    mouthY,
    pourTargetY: bodyHeight + neckHeight * 0.38,
    effectY: baseY + safeFillHeight * 0.7,
    gripY: bodyHeight * 0.62,
    extra: {
      interactionZone: makeAnchor(group, 0, bodyHeight + neckHeight * 0.38, 0, `${name}:interactionZone`),
      dropAnchor: makeAnchor(group, 0, bodyHeight + neckHeight * 0.52, 0, `${name}:dropAnchor`),
      scoopTarget: makeAnchor(group, 0, baseY + safeFillHeight * 0.72, 0, `${name}:scoopTarget`),
    },
  });

  const constraints = {
    innerRadius,
    innerHeight,
    safeFillHeight,
    safePourRadius: neckRadius * 1.25,
    safePourClearance: 0.08,
    tiltLimit: pourPose.tiltLimit ?? 1.05,
    solidSurfaceY,
    effectBounds: {
      min: new THREE.Vector3(-innerRadius, 0, -innerRadius),
      max: new THREE.Vector3(innerRadius, mouthY + 0.12, innerRadius),
    },
  };

  const state = {
    fillRatio: 0,
    fillHeight: 0,
    pourProgress: 0,
    effectIntensity: 0,
  };

  function setSolidLevel(nextFillRatio) {
    const value = clamp(nextFillRatio, 0, 1);
    state.fillRatio = value;
    state.fillHeight = Math.min(safeFillHeight, safeFillHeight * value);
    const normalized = safeFillHeight <= 0 ? 0 : state.fillHeight / safeFillHeight;
    solid.scale.set(1, Math.max(normalized, 0.0001), 1);
    solid.position.y = baseY + state.fillHeight * 0.5;
    solidSurface.position.y = baseY + state.fillHeight;
    const surfaceRadius = innerRadius * (0.94 + normalized * 0.04);
    solidSurface.scale.setScalar(surfaceRadius / (innerRadius * 0.98));
    constraints.solidSurfaceY = solidSurface.position.y;
    anchors.scoopTarget.position.y = baseY + state.fillHeight * 0.82;
    anchors.effectOrigin.position.y = baseY + state.fillHeight * 0.68;
    return {
      fillRatio: state.fillRatio,
      fillHeight: state.fillHeight,
    };
  }

  const basePosition = new THREE.Vector3(...position);
  const baseRotation = new THREE.Euler(...rotation);
  const travel = new THREE.Vector3(...(pourPose.travel ?? [0, 0, 0]));
  const tilt = pourPose.tilt ?? [0.08, 0, -0.72];

  const apparatus = composeApparatus({
    kind: 'solid-reagent-jar',
    family: 'solid-reagent-container',
    group,
    meshes: { body, shoulder, neck, bottom, lid, solid, solidSurface, granules },
    anchors,
    constraints,
    state,
    meta: {
      basePosition,
      baseRotation,
      travel,
      tilt,
      fillMode: 'solid',
      appearance: appearance.name,
    },
  });

  const { labelPlane } = attachFixedPlaneLabel({
    group,
    labelAnchor: anchors.labelAnchor,
    planeGeometry: new THREE.PlaneGeometry(Math.max(radius * 2.55, 0.56), Math.max(bodyHeight * 0.34, 0.36)),
    role: 'vessel-body-label',
  });

  apparatus.controllers = {
    setFillLevel(nextFillRatio) {
      return setSolidLevel(nextFillRatio);
    },
    setLiquidLevel(nextFillRatio) {
      return setSolidLevel(nextFillRatio);
    },
    setPourPose(progress) {
      const value = clamp(progress, 0, 1);
      apparatus.state.pourProgress = value;
      group.position.copy(basePosition).addScaledVector(travel, value);
      group.rotation.set(
        baseRotation.x + tilt[0] * value,
        baseRotation.y + tilt[1] * value,
        baseRotation.z + tilt[2] * value
      );
    },
    setEffectIntensity(value) {
      const intensity = clamp(value, 0, 1);
      apparatus.state.effectIntensity = intensity;
      granules.material.opacity = 0.08 + intensity * 0.26;
    },
  };
  apparatus.validators = [
    () => validateFillLevel(apparatus, apparatus.state.fillHeight),
  ];

  attachLabelController(apparatus, labelPlane, { defaultAccent: '#84ddff' });
  setSolidLevel(fillRatio);
  return apparatus;
}

function createLitmusPaperApparatus({
  parent,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  length = 0.84,
  width = 0.16,
  thickness = 0.01,
  contactRatio = 0.46,
  materials = {},
  color = 0xf6f2e7,
  wetColor = 0xcfd7df,
  wireLength = 0,
  wireRadius = 0.01,
  wireColor = 0x8d96a2,
  stopperRadius = 0,
  stopperHeight = 0.14,
  stopperColor = 0xd0c5a0,
  name = 'litmus-paper',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  applyTransform(group, position, rotation);
  addToParent(parent, group);

  const stripMaterial = cloneMaterial(
    materials.strip,
    new THREE.MeshStandardMaterial({ color, roughness: 0.88, metalness: 0 })
  );
  const contactMaterial = cloneMaterial(
    materials.contact,
    new THREE.MeshStandardMaterial({ color: wetColor, roughness: 0.74, metalness: 0 })
  );

  const strip = new THREE.Mesh(
    new THREE.BoxGeometry(width, length, thickness),
    stripMaterial
  );
  strip.castShadow = true;
  strip.receiveShadow = true;
  group.add(strip);

  const contactPatch = new THREE.Mesh(
    new THREE.BoxGeometry(width * 0.92, length * contactRatio, thickness * 1.1),
    contactMaterial
  );
  contactPatch.position.y = -(length * 0.5) + (length * contactRatio * 0.5);
  contactPatch.position.z = thickness * 0.06;
  group.add(contactPatch);

  const hasProbeAssembly = wireLength > 0 || stopperRadius > 0;
  let wire = null;
  let stopper = null;
  const stripTopY = length * 0.5;
  if (wireLength > 0) {
    wire = new THREE.Mesh(
      new THREE.CylinderGeometry(wireRadius, wireRadius, wireLength, 16),
      cloneMaterial(
        materials.wire,
        new THREE.MeshStandardMaterial({ color: wireColor, roughness: 0.34, metalness: 0.72 })
      )
    );
    wire.position.y = stripTopY + wireLength * 0.5;
    wire.castShadow = true;
    group.add(wire);
  }

  if (stopperRadius > 0) {
    stopper = new THREE.Mesh(
      new THREE.CylinderGeometry(stopperRadius * 0.94, stopperRadius, stopperHeight, 20),
      cloneMaterial(
        materials.stopper,
        new THREE.MeshStandardMaterial({ color: stopperColor, roughness: 0.82, metalness: 0.04 })
      )
    );
    stopper.position.y = stripTopY + Math.max(0, wireLength) + stopperHeight * 0.5;
    stopper.castShadow = true;
    stopper.receiveShadow = true;
    group.add(stopper);
  }

  const tipY = -length * 0.5 + thickness;
  const sampleZoneY = -(length * 0.5) + length * contactRatio * 0.45;
  const stopperSeatY = stopper
    ? stopper.position.y - stopperHeight * 0.5
    : stripTopY + Math.max(0, wireLength);
  const probeGripY = stopper
    ? stopper.position.y + stopperHeight * 0.18
    : stripTopY + Math.max(0, wireLength) + Math.max(length * 0.08, 0.05);
  const anchors = {
    labelAnchor: makeAnchor(group, 0, length * 0.62, 0, `${name}:labelAnchor`),
    gripAnchor: makeAnchor(group, 0, length * 0.24, 0, `${name}:gripAnchor`),
    probeGrip: makeAnchor(group, 0, probeGripY, 0, `${name}:probeGrip`),
    stopperSeat: makeAnchor(group, 0, stopperSeatY, 0, `${name}:stopperSeat`),
    tipAnchor: makeAnchor(group, 0, tipY, 0, `${name}:tipAnchor`),
    sampleZone: makeAnchor(group, 0, sampleZoneY, 0, `${name}:sampleZone`),
  };

  const state = {
    wetness: 0,
    indicatorColor: new THREE.Color(color),
    contactPose: 0,
  };

  const basePosition = new THREE.Vector3(...position);
  const baseRotation = new THREE.Euler(...rotation);
  const travel = new THREE.Vector3(0, -length * 0.18, 0);
  const tilt = [0.18, 0, -0.22];

  const apparatus = composeApparatus({
    kind: 'litmus-paper',
    family: 'indicator-tool',
    group,
    meshes: { strip, contactPatch, wire, stopper },
    anchors,
    constraints: {
      tipInset: length * 0.04,
      contactLength: length * contactRatio,
      contactWidth: width * 0.92,
      effectBounds: {
        min: new THREE.Vector3(-width * 0.6, -length * 0.52, -thickness * 1.5),
        max: new THREE.Vector3(
          Math.max(width * 0.6, stopperRadius * 1.08),
          Math.max(length * 0.52, stopperSeatY + stopperHeight * 1.05),
          Math.max(thickness * 1.5, stopperRadius * 1.08)
        ),
      },
    },
    state,
    meta: {
      basePosition,
      baseRotation,
      hasProbeAssembly,
    },
  });

  const { labelPlane } = attachFixedPlaneLabel({
    group,
    labelAnchor: anchors.labelAnchor,
    planeGeometry: new THREE.PlaneGeometry(0.92, 0.36),
    role: 'floating-badge',
  });

  apparatus.controllers = {
    setIndicatorColor(nextColor) {
      const value = new THREE.Color(nextColor);
      state.indicatorColor.copy(value);
      strip.material.color.lerpColors(new THREE.Color(color), value, 0.4 + state.wetness * 0.4);
      contactPatch.material.color.copy(value);
    },
    setWetness(value) {
      const wetness = clamp(value, 0, 1);
      state.wetness = wetness;
      contactPatch.material.opacity = 0.18 + wetness * 0.82;
      contactPatch.material.transparent = contactPatch.material.opacity < 0.999;
      strip.material.color.lerpColors(new THREE.Color(color), state.indicatorColor, wetness * 0.35);
    },
    setContactPose(progress) {
      const value = clamp(progress, 0, 1);
      state.contactPose = value;
      group.position.copy(basePosition).addScaledVector(travel, value);
      group.rotation.set(
        baseRotation.x + tilt[0] * value,
        baseRotation.y + tilt[1] * value,
        baseRotation.z + tilt[2] * value
      );
    },
  };
  attachLabelController(apparatus, labelPlane, { defaultAccent: '#7d4fd3' });
  apparatus.validators = [];
  apparatus.controllers.setIndicatorColor(color);
  apparatus.controllers.setWetness(0);
  return apparatus;
}

function createNailPatinaTexture({
  width = 256,
  height = 1024,
  base = '#b66a3c',
  dark = '#5d3116',
  highlight = '#d69463',
  alphaBias = 0.52,
} = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, width, height);

  const baseGradient = ctx.createLinearGradient(0, 0, 0, height);
  baseGradient.addColorStop(0, base);
  baseGradient.addColorStop(0.26, highlight);
  baseGradient.addColorStop(0.55, base);
  baseGradient.addColorStop(1, dark);
  ctx.fillStyle = baseGradient;
  ctx.fillRect(0, 0, width, height);

  const edgeShade = ctx.createLinearGradient(0, 0, width, 0);
  edgeShade.addColorStop(0, 'rgba(52, 24, 10, 0.92)');
  edgeShade.addColorStop(0.18, 'rgba(138, 80, 43, 0.18)');
  edgeShade.addColorStop(0.5, 'rgba(255, 221, 190, 0.18)');
  edgeShade.addColorStop(0.82, 'rgba(126, 72, 39, 0.2)');
  edgeShade.addColorStop(1, 'rgba(49, 22, 8, 0.9)');
  ctx.fillStyle = edgeShade;
  ctx.fillRect(0, 0, width, height);

  for (let index = 0; index < 44; index += 1) {
    const y = (index / 43) * height;
    const bandHeight = height * (0.016 + Math.random() * 0.038);
    const alpha = 0.03 + Math.random() * 0.065;
    ctx.fillStyle = `rgba(255, 232, 210, ${alpha.toFixed(3)})`;
    ctx.fillRect(0, y, width, bandHeight);
  }

  for (let index = 0; index < 170; index += 1) {
    const x = width * (0.1 + Math.random() * 0.8);
    const y = Math.random() * height;
    const rx = width * (0.03 + Math.random() * 0.12);
    const ry = height * (0.004 + Math.random() * 0.018);
    const alpha = 0.08 + Math.random() * 0.2;
    ctx.fillStyle = Math.random() > 0.45
      ? `rgba(93, 49, 22, ${alpha.toFixed(3)})`
      : `rgba(214, 148, 99, ${alpha.toFixed(3)})`;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, Math.random() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }

  for (let index = 0; index < 96; index += 1) {
    const x = width * (0.16 + Math.random() * 0.68);
    const y = Math.random() * height;
    const streakWidth = width * (0.008 + Math.random() * 0.024);
    const streakHeight = height * (0.06 + Math.random() * 0.2);
    const streak = ctx.createLinearGradient(x, y, x, y + streakHeight);
    streak.addColorStop(0, 'rgba(255, 214, 179, 0)');
    streak.addColorStop(0.3, `rgba(255, 214, 179, ${(0.08 + Math.random() * 0.15).toFixed(3)})`);
    streak.addColorStop(1, 'rgba(86, 43, 18, 0)');
    ctx.fillStyle = streak;
    ctx.fillRect(x, y, streakWidth, streakHeight);
  }

  const alphaCanvas = document.createElement('canvas');
  alphaCanvas.width = width;
  alphaCanvas.height = height;
  const alphaCtx = alphaCanvas.getContext('2d');
  alphaCtx.fillStyle = '#000';
  alphaCtx.fillRect(0, 0, width, height);

  for (let index = 0; index < 220; index += 1) {
    const x = width * (0.08 + Math.random() * 0.84);
    const y = Math.random() * height;
    const rx = width * (0.02 + Math.random() * 0.11);
    const ry = height * (0.003 + Math.random() * 0.02);
    const intensity = alphaBias + Math.random() * (1 - alphaBias);
    alphaCtx.fillStyle = `rgba(255, 255, 255, ${intensity.toFixed(3)})`;
    alphaCtx.beginPath();
    alphaCtx.ellipse(x, y, rx, ry, Math.random() * Math.PI, 0, Math.PI * 2);
    alphaCtx.fill();
  }

  for (let index = 0; index < 58; index += 1) {
    const y = Math.random() * height;
    const h = height * (0.012 + Math.random() * 0.02);
    const band = alphaCtx.createLinearGradient(0, y, width, y + h);
    band.addColorStop(0, 'rgba(255, 255, 255, 0)');
    band.addColorStop(0.12, `rgba(255, 255, 255, ${(0.5 + Math.random() * 0.24).toFixed(3)})`);
    band.addColorStop(0.5, `rgba(255, 255, 255, ${(0.14 + Math.random() * 0.18).toFixed(3)})`);
    band.addColorStop(0.88, `rgba(255, 255, 255, ${(0.46 + Math.random() * 0.26).toFixed(3)})`);
    band.addColorStop(1, 'rgba(255, 255, 255, 0)');
    alphaCtx.fillStyle = band;
    alphaCtx.fillRect(0, y, width, h);
  }

  const colorTexture = new THREE.CanvasTexture(canvas);
  colorTexture.wrapS = THREE.ClampToEdgeWrapping;
  colorTexture.wrapT = THREE.RepeatWrapping;
  colorTexture.repeat.set(1, 1);
  colorTexture.needsUpdate = true;

  const alphaTexture = new THREE.CanvasTexture(alphaCanvas);
  alphaTexture.wrapS = THREE.ClampToEdgeWrapping;
  alphaTexture.wrapT = THREE.RepeatWrapping;
  alphaTexture.repeat.set(1, 1);
  alphaTexture.needsUpdate = true;

  return { colorTexture, alphaTexture };
}

function createIronNailApparatus({
  parent,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  length = 1.65,
  radius = 0.055,
  headRadius = 0.16,
  headThickness = 0.07,
  tipLength = 0.24,
  materials = {},
  name = 'iron-nail',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  applyTransform(group, position, rotation);
  addToParent(parent, group);

  const { colorTexture: patinaColorMap, alphaTexture: patinaAlphaMap } = createNailPatinaTexture();

  const steelMaterial = cloneMaterial(
    materials.steel,
    new THREE.MeshStandardMaterial({ color: 0xa8b0ba, roughness: 0.34, metalness: 0.86 })
  );
  const copperMaterial = cloneMaterial(
    materials.copperCoat,
    new THREE.MeshStandardMaterial({
      color: 0xb96838,
      roughness: 0.7,
      metalness: 0.24,
      emissive: 0x3a190b,
      emissiveIntensity: 0.08,
      map: patinaColorMap,
      alphaMap: patinaAlphaMap,
      transparent: true,
      opacity: 0,
      depthWrite: false,
    })
  );

  const head = new THREE.Mesh(
    new THREE.CylinderGeometry(headRadius, headRadius, headThickness, 28),
    steelMaterial
  );
  head.rotation.z = Math.PI / 2;
  head.position.x = -length * 0.5;
  head.castShadow = true;
  group.add(head);

  const headCoat = new THREE.Mesh(
    new THREE.CylinderGeometry(headRadius * 1.03, headRadius * 1.03, headThickness * 1.02, 28),
    copperMaterial
  );
  headCoat.rotation.z = Math.PI / 2;
  headCoat.position.copy(head.position);
  group.add(headCoat);

  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, length - tipLength, 18),
    steelMaterial
  );
  body.rotation.z = Math.PI / 2;
  body.position.x = -tipLength * 0.5 + 0.02;
  body.castShadow = true;
  group.add(body);

  const tip = new THREE.Mesh(
    new THREE.ConeGeometry(radius, tipLength, 18),
    steelMaterial
  );
  tip.rotation.z = -Math.PI / 2;
  tip.position.x = length * 0.5 - tipLength * 0.5;
  tip.castShadow = true;
  group.add(tip);

  const tipCoat = new THREE.Mesh(
    new THREE.ConeGeometry(radius * 1.07, tipLength * 1.02, 18),
    copperMaterial
  );
  tipCoat.rotation.z = -Math.PI / 2;
  tipCoat.position.copy(tip.position);
  group.add(tipCoat);

  const copperCoat = new THREE.Mesh(
    new THREE.CylinderGeometry(radius * 1.14, radius * 1.14, length - tipLength * 1.2, 18),
    copperMaterial
  );
  copperCoat.rotation.z = Math.PI / 2;
  copperCoat.position.copy(body.position);
  group.add(copperCoat);

  const anchors = {
    labelAnchor: makeAnchor(group, 0, radius * 7.8, 0, `${name}:labelAnchor`),
    gripAnchor: makeAnchor(group, -length * 0.25, 0, 0, `${name}:gripAnchor`),
    tipAnchor: makeAnchor(group, length * 0.5, 0, 0, `${name}:tipAnchor`),
    sampleZone: makeAnchor(group, length * 0.22, 0, 0, `${name}:sampleZone`),
    interactionZone: makeAnchor(group, length * 0.28, 0, 0, `${name}:interactionZone`),
    effectOrigin: makeAnchor(group, length * 0.2, 0, 0, `${name}:effectOrigin`),
  };

  const state = {
    copperCoating: 0,
  };

  const apparatus = composeApparatus({
    kind: 'iron-nail',
    family: 'solid-metal-sample',
    group,
    meshes: { head, headCoat, body, tip, tipCoat, copperCoat },
    anchors,
    constraints: {
      length,
      radius,
      contactRadius: radius * 2.2,
      effectBounds: {
        min: new THREE.Vector3(-length * 0.55, -radius * 2.5, -radius * 2.5),
        max: new THREE.Vector3(length * 0.55, radius * 2.5, radius * 2.5),
      },
    },
    state,
  });

  const { labelPlane } = attachFixedPlaneLabel({
    group,
    labelAnchor: anchors.labelAnchor,
    planeGeometry: new THREE.PlaneGeometry(1.42, 0.58),
    accent: '#bd7543',
    role: 'floating-badge',
  });
  attachLabelController(apparatus, labelPlane, { defaultAccent: '#bd7543' });

  apparatus.controllers = {
    ...(apparatus.controllers || {}),
    setCopperCoating(value) {
      const coating = clamp(value, 0, 1);
      state.copperCoating = coating;
      const coatOpacity = coating * 0.9;
      copperCoat.material.opacity = coatOpacity;
      copperCoat.material.roughness = 0.88 - coating * 0.1;
      copperCoat.material.metalness = 0.2 + coating * 0.08;
      copperCoat.material.emissiveIntensity = 0.03 + coating * 0.08;
      body.material.color.lerpColors(new THREE.Color(0xa8b0ba), new THREE.Color(0x8a7c70), coating * 0.35);
      head.material.color.lerpColors(new THREE.Color(0xa8b0ba), new THREE.Color(0x86786e), coating * 0.22);
      tip.material.color.lerpColors(new THREE.Color(0xa8b0ba), new THREE.Color(0x7e6d61), coating * 0.28);
    },
  };

  apparatus.controllers.setCopperCoating(0);
  return apparatus;
}

